package me.ag2s.epublib.epub
import me.ag2s.epublib.domain.EpubBook
class BookProcessorPipeline(private var bookProcessors: MutableList<BookProcessor>? = null) : BookProcessor { override fun processBook(book: EpubBook): EpubBook { var result = book; bookProcessors?.forEach { try { result = it.processBook(result) } catch (e: Exception) { e.printStackTrace() } }; return result }; fun addBookProcessor(value: BookProcessor) { if (bookProcessors == null) bookProcessors = ArrayList(); bookProcessors!!.add(value) }; fun addBookProcessors(values: Collection<BookProcessor>) { if (bookProcessors == null) bookProcessors = ArrayList(); bookProcessors!!.addAll(values) }; fun getBookProcessors() = bookProcessors; fun setBookProcessingPipeline(value: MutableList<BookProcessor>?) { bookProcessors = value } }
